#include "testlib.h"
#include <bits/stdc++.h>
using namespace std;
int main(int argc,char**argv){registerTestlibCmd(argc,argv);int n=inf.readInt(),m=inf.readInt();vector<long long>id;id.reserve(m);for(int i=0;i<m;i++){int u=inf.readInt(),v=inf.readInt();id.push_back(1LL*u*(n+1)+v);}sort(id.begin(),id.end());auto check=[&](InStream &s,bool jury){auto fail=[&](const char*z){quitf(jury?_fail:_wa,"%s",z);};string t=s.readToken();if(t!="Yes"&&t!="No")fail("expected Yes or No");if(t=="No"){if(!s.seekEof())fail("extra output after No");return false;}vector<char>used(m);for(int k=0;k<m/2;k++){int u=s.readInt(1,n),v=s.readInt(1,n),x=s.readInt(1,n),y=s.readInt(1,n);if(v!=x&&y!=u)fail("edges cannot concatenate");for(auto [a,b]:{pair<int,int>{u,v},{x,y}}){long long key=1LL*a*(n+1)+b;auto it=lower_bound(id.begin(),id.end(),key);if(it==id.end()||*it!=key)fail("edge absent from input");int at=it-id.begin();if(used[at])fail("edge repeated");used[at]=1;}}if(!s.seekEof())fail("extra output");return true;};bool truth=check(ans,true),actual=check(ouf,false);if(!truth&&actual)quitf(_fail,"valid contestant witness contradicts jury No");if(truth!=actual)quitf(_wa,"incorrect feasibility claim");quitf(_ok,"valid edge pairing");}
